import { refresh } from 'next/cache'
import { cookies } from 'next/headers'

const notificationCookie = 'notifications-enabled'

export default async function Home() {
  const notificationsEnabled = (await cookies()).get(notificationCookie)?.value === 'true'

  async function toggleNotifications() {
    'use server'

    const cookieStore = await cookies()
    const enabled = cookieStore.get(notificationCookie)?.value === 'true'
    cookieStore.set(notificationCookie, String(!enabled), {
      httpOnly: true,
      sameSite: 'lax',
      path: '/',
      maxAge: 60 * 60 * 24 * 365,
    })

    refresh()
  }

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are {notificationsEnabled ? 'on' : 'off'}.</p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn {notificationsEnabled ? 'off' : 'on'} notifications
        </button>
      </form>
    </main>
  )
}

