node - <<'NODE'
const url = 'http://localhost:3333/'
let cookie = ''
for (const expected of ['off', 'on', 'off']) {
  const res = await fetch(url, { headers: cookie ? { Cookie: cookie } : {} })
  const html = (await res.text()).replace(/<!--.*?-->/gs, '')
  const status = html.match(/Notifications are (on|off)\./)?.[1]
  console.log(`GET /: ${res.status}, notifications ${status}`)
  if (status !== expected) process.exit(1)
  if (expected === 'off' && cookie) break
  const actionId = html.match(/name="(\$ACTION_ID_[a-z0-9]+)"/)?.[1]
  if (!actionId) throw new Error('Form action ID not found')
  const form = new FormData()
  form.append(actionId, '')
  const post = await fetch(url, { method: 'POST', body: form, redirect: 'manual', headers: cookie ? { Cookie: cookie } : {} })
  const postHtml = (await post.text()).replace(/<!--.*?-->/gs, '')
  const next = expected === 'off' ? 'on' : 'off'
  cookie = post.headers.get('set-cookie')?.split(';')[0] ?? ''
  console.log(`POST /: ${post.status}, location ${post.headers.get('location')}, cookie ${cookie}, response notifications ${postHtml.match(/Notifications are (on|off)\./)?.[1]}`)
  if (post.status !== 200 || post.headers.get('location') || !cookie || !postHtml.includes(`Notifications are ${next}.`)) process.exit(1)
}
NODE

